#!/bin/bash
# Print the three most frequent IPs in access.log, one per line.
# Ties broken by first appearance in the log.
set -eu

awk '
{
    ip = $1
    if (!(ip in count)) order[++n] = ip
    count[ip]++
}
END {
    # Stable selection: sort indices by count desc, then first-seen asc,
    # via simple repeated selection (n is small in practice, but keep it
    # general with O(n^2) selection for stability without external tools).
    for (out = 1; out <= 3 && out <= n; out++) {
        best = 0
        for (i = 1; i <= n; i++) {
            if (order[i] in picked) continue
            if (best == 0 || count[order[i]] > count[order[best]]) best = i
        }
        picked[order[best]] = 1
        print order[best]
    }
}
' access.log
